const item = $input.item.json;
const mall_id = item.mall_id;
const cmc_manager = item.cmc_manager;

// 오늘 날짜 (YYYY-MM-DD 형식)
const now = new Date();
const calc_date = now.toISOString().split('T')[0];

// 2025년 2월부터 7월까지의 기간 설정
const months = [
  { month: '2025-02', start: '2025-02-01', end: '2025-02-28' },
  { month: '2025-03', start: '2025-03-01', end: '2025-03-31' },
  { month: '2025-04', start: '2025-04-01', end: '2025-04-30' },
  { month: '2025-05', start: '2025-05-01', end: '2025-05-31' },
  { month: '2025-06', start: '2025-06-01', end: '2025-06-30' },
  { month: '2025-07', start: '2025-07-01', end: '2025-07-31' }
];

// 각 월별로 데이터 요청 준비
const requests = months.map(m => ({
  json: {
    mall_id,
    cmc_manager,
    calc_date,
    month: m.month,
    startDate: m.start,
    endDate: m.end
  }
}));

return requests;

const item = $input.item.json;
const mall_id = item.mall_id;
const cmc_manager = item.cmc_manager;
const calc_date = item.calc_date;
const month = item.month; // 예: '2025-02'

// PostgreSQL 쿼리 결과에서 매출 데이터 추출
let monthly_sales = 0;

// 쿼리 결과가 있고 데이터가 있는 경우
if ($input.item.json && Array.isArray($input.item.json)) {
  // 해당 월의 데이터 찾기
  const salesData = $input.item.json.find(row => {
    // row.month는 '202502' 형태, month는 '2025-02' 형태
    // '2025-02'를 '202502'로 변환하여 비교
    const targetMonth = month.replace('-', '');
    return String(row.month) === targetMonth;
  });

  if (salesData) {
    monthly_sales = salesData.sum_sal || 0;
  }
}

return [{
  json: {
    mall_id,
    cmc_manager,
    calc_date,
    month,
    monthly_sales
  }
}];

const salesData = $input.all();
const firstItem = salesData[0];
const mall_id = firstItem.json.mall_id;
const cmc_manager = firstItem.json.cmc_manager;
const calc_date = firstItem.json.calc_date;

// 월별 매출 데이터를 객체로 정리
const monthlyData = {};
salesData.forEach(item => {
  monthlyData[item.json.month] = item.json.monthly_sales || 0;
});

// 이전 3개월 평균 계산 (2025년 2,3,4월)
const prev_3_months = ['2025-02', '2025-03', '2025-04'];
const prev_sum = prev_3_months.reduce((sum, month) => sum + (monthlyData[month] || 0), 0);
const avg_sum_90_prev = prev_sum / 3;

// 최근 3개월 평균 계산 (2025년 5,6,7월)
const recent_3_months = ['2025-05', '2025-06', '2025-07'];
const recent_sum = recent_3_months.reduce((sum, month) => sum + (monthlyData[month] || 0), 0);
const avg_sum_90_recent = recent_sum / 3;

// zScore_Raw 시트 형식에 맞춰 데이터 구성
const result = {
  calc_date,                    // 계산 기준일
  mall_id,                      // 쇼핑몰 아이디
  cmc_manager,                   // 담당자 ID
  cmc_manager_name: cmc_manager, // 담당자 이름 (임시로 동일하게 설정)
  pg_join_date: '',             // PG 가입일 (패스)
  pg_recency_days: 0,           // PG 가입 후 경과일수 (패스)
  '2025-02': monthlyData['2025-02'] || 0,  // 2025년 2월 매출
  '2025-03': monthlyData['2025-03'] || 0,  // 2025년 3월 매출
  '2025-04': monthlyData['2025-04'] || 0,  // 2025년 4월 매출
  '2025-05': monthlyData['2025-05'] || 0,  // 2025년 5월 매출
  '2025-06': monthlyData['2025-06'] || 0,  // 2025년 6월 매출
  '2025-07': monthlyData['2025-07'] || 0,  // 2025년 7월 매출
  avg_sum_90_prev,              // 이전 3개월 평균 매출
  avg_sum_90_recent,            // 최근 3개월 평균 매출
  '2025-06': monthlyData['2025-06'] || 0,  // 이전 30일 (6월)
  '2025-07': monthlyData['2025-07'] || 0,  // 최근 30일 (7월)
  sfdc_has_history: false,      // SF 영업이력 (패스)
  sfdc_gap_flag: 0,             // SF 갭 플래그 (패스)
  ad_script_detect: 0,          // 광고 스크립트 감지 (패스)
  fetch_status: 200,            // 데이터 가져오기 상태
  fetch_error: '',              // 에러 메시지
  updated_at: new Date().toISOString().replace('T', ' ').substring(0, 19)  // 업데이트 시간
};

return [{ json: result }];
